.lb.mb-tema{background:var(--dm-f)}
.lb.mb-tema .lb-side{background:var(--dm-riel-lado)}
.lb.mb-tema .lb-tabbar{background:var(--dm-barra);box-shadow:inset 0 1px 0 0 rgba(255,255,255,.06),0 -12px 30px rgba(0,0,0,.6)}


.lb.mb-tema .lb-tab::after{background:var(--dm-p-tab)}
.lb.mb-tema .lb-marca{background:linear-gradient(180deg,var(--dm-p-tab),rgba(var(--dm-p-rgb),.35))!important}
.lb.mb-tema .lb-nav::before,.lb.mb-tema .lb-trow::before{background:var(--dm-p)}
.lb.mb-tema .lb-live{background:var(--dm-p-texto);box-shadow:0 0 10px rgba(var(--dm-p-rgb),.9)}


.lb.mb-tema .lb-win{animation-name:dmWin}
@keyframes dmWin{0%{opacity:0;transform:translateY(-18px) scale(.985)}55%{opacity:1;background:rgba(var(--dm-p-rgb),.12)}100%{opacity:1;transform:none;background:transparent}}
.lb.mb-tema .lb-win::after{background:linear-gradient(100deg,rgba(255,255,255,0),rgba(var(--dm-p-claro-rgb),.3),rgba(255,255,255,0))}


.lb.mb-tema .lb-prov:hover{box-shadow:inset 0 0 0 1px rgba(var(--dm-p-rgb),.45)}
.lb.mb-tema .lb-sug-n em{color:var(--dm-p-texto)}
.lb.mb-tema .lb-prow:hover h2{color:var(--dm-p-texto)}
.lb.mb-tema .lb-ord[data-on="1"]{background:rgba(var(--dm-p-rgb),.14);box-shadow:inset 0 0 0 1px rgba(var(--dm-p-rgb),.45);color:var(--dm-p-texto)}
.lb.mb-tema .lb-fav[data-on="1"] path{fill:var(--dm-p);stroke:var(--dm-p)}


.lb.mb-tema button:focus-visible,.lb.mb-tema [role="button"]:focus-visible,.lb.mb-tema .lb-trow-ir:focus-visible,.lb.mb-tema .lb-fav:focus-visible{outline-color:var(--dm-p)}


.lb.mb-tema .lb-busca-campo{background:var(--dm-f1)}
.lb.mb-tema .lb-btn:active{box-shadow:inset 0 0 0 1px rgba(255,255,255,.09),inset 0 2px 4px rgba(var(--dm-b-activo-rgb),.32),0 1px 2px rgba(0,0,0,.32)}



.lb.mb-tema .lb-azar,.lb.mb-tema .lb-sug{background:var(--dm-sup)}
.lb.mb-tema .lb-azar:hover,.lb.mb-tema .lb-sug-r:hover,.lb.mb-tema .lb-sug-r:focus-visible{background:var(--dm-n-cerrar)}
.lb.mb-tema .lb-sug-art{background-color:var(--dm-n-cerrar)}
.lb.mb-tema .lb-tbl{background:var(--dm-riel)}

.lb.mb-tema button.lb-btn[aria-label^="Ver los "]{background:var(--dm-sup)!important;border-color:var(--dm-filo-campo)!important}
.lb.mb-tema .lb-thumb{background-color:var(--dm-n-cerrar)!important}



.dm-filtro img:is([src*="rushybet/rushybet-logo"],[src*="rushybet/v3/mark"],[src*="rushybet/v3/textura-banner"],[src*="rushybet/v3/cut-"],[src*="rushybet/v2/pop-"],[src*="rushybet/v2/recarga-fichas"]){filter:var(--dm-img-filtro)}


.mb-app .rb-input:focus{border-color:var(--dm-b-borde)!important;box-shadow:0 0 0 3px rgba(var(--dm-p-rgb),.16)!important}
.mb-app .rb-focus:focus-visible{outline-color:var(--dm-p)}
