.dm-aro .lb.mb-tema .lb-side::after{content:'';position:absolute;top:0;bottom:0;right:0;width:2px;pointer-events:none;background:var(--dm-anillo)}
.dm-aro .lb.mb-tema .lb-tabbar::before{content:'';position:absolute;left:0;right:0;top:0;height:2px;pointer-events:none;background:var(--dm-anillo)}
.dm-aro .lb.mb-tema .lb-promo::after,.dm-aro .lb.mb-tema .lb-hero-panel::after{content:'';position:absolute;inset:0;border-radius:20px;padding:2px;pointer-events:none;background:var(--dm-anillo);-webkit-mask:linear-gradient(#000 0 0) content-box,linear-gradient(#000 0 0);-webkit-mask-composite:xor;mask:linear-gradient(#000 0 0) content-box,linear-gradient(#000 0 0);mask-composite:exclude}



